import { deepStrictEqual, strictEqual, throws } from 'node:assert/strict';
import { basename, dirname, join, resolve } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath } from 'node:url';
import { apiText, listDifferences, publishedPackageDirs } from './api.mjs';
import { readPackageApi } from './read-api.mjs';

const here = dirname(fileURLToPath(import.meta.url));

describe('apiText', () => {
  it('puts a header above the lines and ends with a newline', () => {
    strictEqual(
      apiText(['.: const a: 1', '.: const b: 2']),
      '# Generated by `pnpm api:update` from the built declarations. Do not edit by hand.\n.: const a: 1\n.: const b: 2\n',
    );
  });
});

describe('listDifferences', () => {
  it('shows removed and added lines', () => {
    deepStrictEqual(
      listDifferences(
        apiText(['.: const a: 1', '.: const b: 2']),
        apiText(['.: const a: 1', '.: const c: 3']),
      ),
      ['- .: const b: 2', '+ .: const c: 3'],
    );
  });

  it('says how many more lines changed than it shows', () => {
    const many = Array.from({ length: 12 }, (_, index) => `.: const v${index}: ${index}`);
    const shown = listDifferences(apiText([]), apiText(many));
    strictEqual(shown.length, 11);
    strictEqual(shown.at(-1), '  ... and 2 more');
  });

  it('reports a file that differs only in order or spacing', () => {
    deepStrictEqual(listDifferences('.: b\n.: a\n', '.: a\n.: b\n'), [
      '  (same lines, different order or spacing)',
    ]);
  });
});

describe('publishedPackageDirs', () => {
  it('lists every package under packages/9-public/@prisma', () => {
    const dirs = publishedPackageDirs(resolve(here, '..', '..'));
    strictEqual(dirs.length, 22);
    strictEqual(basename(dirs[0]), 'orm-better-auth');
  });
});

describe('readPackageApi', () => {
  it('tells the reader to build first when a declaration file is missing', () => {
    throws(
      () => readPackageApi(join(here, 'fixtures', 'unbuilt')),
      /lib\/index\.d\.mts\. Run `pnpm build` first\./,
    );
  });
});
